settings.cellContentFunction:
// Reuse rate = Reused / Generated (D3). External source: no rate.
var src = String(entity['Source'] || entity['data_source'] || '');
if (src.indexOf('external') >= 0) { return '–'; }
var g = parseFloat(entity['Generated'] !== undefined ? entity['Generated'] : entity['generated_g']);
var r = parseFloat(entity['Reused'] !== undefined ? entity['Reused'] : entity['reused_g']);
if (isNaN(g)) { return 'check: ' + Object.keys(entity).join(', '); }
if (!g) { return '–'; }
return (100 * (isNaN(r) ? 0 : r) / g).toFixed(1) + ' %';

// Next emptying forecast -> readable date (Helsinki time). No forecast -> "–".
if (value === undefined || value === null || value === '') { return '–'; }
var t = Number(String(value).replace(/[^0-9.]/g, ''));
if (!t) { return '–'; }
var d = new Date(t);
var txt = d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'numeric', timeZone: 'Europe/Helsinki' });
if (t < Date.now()) { return txt + ' (due)'; }
return txt;

rowClick.customFunction:
// Open the right detail page: external kitchen data -> kitchen_detail, measuring points -> field_detail.
var EXTERNAL_POINTS = ['SK-01'];
var stateId = EXTERNAL_POINTS.indexOf(entityName) >= 0 ? 'kitchen_detail' : 'field_detail';
var params = { entityId: entityId, entityName: entityName, entityLabel: entityLabel };
widgetContext.stateController.openState(stateId, params, false);

totalValueColor.colorFunction:
var temperature = value;
if (typeof temperature !== undefined) {
  var percent = (temperature + 60)/120 * 100;
  return tinycolor.mix('blue', 'red', percent).toHexString();
}
return 'blue';

settings.markdownTextPattern:
// Forecast emptying date card (next_emptying_ts, calculated field "Next emptying forecast").
var row = (data && data.length) ? data[0] : {};
var v = row['next_emptying_ts'];
var t = Number(String(v === undefined || v === null ? '' : v).replace(/[^0-9.]/g, ''));
var txt = 'No forecast yet';
var note = '';
if (t) {
  txt = new Date(t).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Europe/Helsinki' });
  if (t < Date.now()) { note = '<div style="font-size:14px;color:#d32f2f;margin-top:6px">due – no emptying recorded yet</div>'; }
}
return '<div style="height:100%;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center">' +
  '<div style="font-size:15px;color:#757575;letter-spacing:0.5px">Forecast emptying date</div>' +
  '<div style="font-size:36px;font-weight:600;margin-top:8px">' + txt + '</div>' + note + '</div>';

